import { tags } from "typia";

/**
 * Metrics tracking the quality and consistency of moderation actions.
 *
 * Tracks appeal rates, overturn rates, and feedback from users regarding
 * moderator decisions to evaluate fairness and consistency of moderation
 * practices.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardModerationEffectivenessMetrics = {
  /**
   * Rate of appeals filed by users against moderator decisions.
   *
   * Represents the proportion of moderator actions that are appealed by
   * users. Calculated as the number of appeals submitted divided by total
   * moderation actions taken.
   *
   * A high appeal rate may indicate inconsistent or poorly communicated
   * moderation decisions, while a low rate suggests high moderator
   * consistency and community trust in moderation outcomes.
   */
  appealRate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Percentage of appealed moderation decisions that were subsequently
   * overturned.
   *
   * Represents the rate at which appeals result in moderator decisions being
   * reversed. Calculated as overturned decisions divided by total appeals.
   *
   * A higher overturn rate may indicate moderation decisions that lack clear
   * justification or violate community standards, while a low rate indicates
   * consistent application of rules.
   */
  overturnRate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Composite score evaluating the quality and consistency of moderator
   * actions.
   *
   * Calculated from aggregated feedback points including appeal outcomes,
   * user satisfaction ratings, timing effectiveness, and adherence to
   * documentation. Higher scores indicate more reliable and trustworthy
   * moderation.
   *
   * This metric combines multiple indicators into a single normalized score
   * for easy monitoring of moderator performance over time.
   */
  reviewQualityScore: number & tags.Minimum<0> & tags.Maximum<10>;

  /**
   * Average user satisfaction rating for moderator interventions.
   *
   * Collected through post-moderation feedback surveys where users rate their
   * experience with moderator decisions. Ratings are on a 1-5 scale.
   *
   * This direct feedback from the community provides insight into perceived
   * fairness, transparency, and responsiveness of moderator actions.
   */
  userSatisfactionRating: number & tags.Minimum<0> & tags.Maximum<5>;

  /**
   * Statistical measure of how consistently moderators apply rules across
   * different content types and users.
   *
   * Calculated by analyzing variance in decision outcomes for similar content
   * items across different moderators. Higher values indicate greater
   * consistency in rule application.
   *
   * This metric helps identify individual moderators who may be applying
   * rules inconsistently and need additional training.
   */
  moderatorConsistencyIndex: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Average time in hours from report submission to initial moderator review.
   *
   * Measures latency between when a report is filed and when a moderator
   * first acts on it (marks as reviewed).
   *
   * This metric assesses responsiveness and helps identify bottlenecks in the
   * moderation workflow.
   */
  initialResponseTimeAvg: number & tags.Minimum<0>;

  /**
   * Average time in hours from report submission to final resolution.
   *
   * Measures total time from report submission to final moderator decision
   * (approve, remove, warn).
   *
   * This metric reflects overall efficiency of the moderation process and
   * highlights potential delays in case management.
   */
  finalResolutionTimeAvg: number & tags.Minimum<0>;

  /**
   * Percentage of moderation decisions that are escalated to senior
   * moderators for review.
   *
   * Represents the proportion of cases deemed complex or contentious by
   * initial moderators, requiring higher-level review.
   *
   * A high escalation rate may indicate gaps in junior moderator training or
   * complex policy interpretation issues.
   */
  escalationRate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Score reflecting adherence to legal and regulatory compliance standards
   * in moderation practices.
   *
   * Constructed from automated checks of moderation actions against
   * documented policies, retention schedules, and legal requirements.
   *
   * Higher scores indicate strong compliance posture and reduced legal risk
   * for the platform.
   */
  complianceAuditScore: number & tags.Minimum<0> & tags.Maximum<100>;

  /**
   * Metric assessing whether moderation actions are applied equitably across
   * different user groups.
   *
   * Calculated by comparing action rates across demographic segments to
   * ensure no group is disproportionately targeted or protected.
   *
   * This ensures fair application of moderation rules and helps prevent
   * discrimination in platform governance.
   */
  enforcementEquityIndex: number & tags.Minimum<0> & tags.Maximum<1>;
};
